insert into cisco.cisco_decks (id, slug, title, sermon_id, metadata)
insert into cisco.cisco_slides (deck_id, position, html, outline_html, bg, notes)
values
  ('c1000000-0000-4000-8000-000000000003', 1, '<p class="kicker">The Cisco Church</p><div class="rule-line"></div><h1>Open Water Faith</h1><p class="sub">Don''t miss the adventure because you never left the shore.</p>', '<p><strong>Open Water Faith</strong> — title up. Hold through the welcome.</p>', 'shore', 'Hold through the welcome.'),
  ('c1000000-0000-4000-8000-000000000003', 2, '', '<p><strong>Noah and the ark.</strong> We can do a lot of things with boats. In Genesis, God had Noah build an ark — built on dry ground, but it wasn''t designed for dry ground. Its purpose could only be realized when the water came.</p>', 'shore', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 3, '<h2 class="stage" data-stage="1">It''s easy to be satisfied with what a boat can do&hellip;</h2><h2 class="stage" data-stage="2">&hellip;without ever experiencing what it was designed to do.</h2>', '<p>It''s easy to be satisfied with what a boat can do&hellip; &hellip;without ever experiencing what it was designed to do.</p>', 'shore', 'One click — the second line lands by itself after a beat.'),
  ('c1000000-0000-4000-8000-000000000003', 4, '<blockquote>What if we spend our lives trying to keep the boat where it feels safest instead of discovering what it was built for?</blockquote>', '<p>What if we spend our lives trying to keep the boat where it feels safest instead of discovering what it was built for?</p>', 'shore', 'Ask the room. Let it sit.'),
  ('c1000000-0000-4000-8000-000000000003', 5, '', '<p><strong>Story — the glass-bottom boat.</strong> Grade school field trip: Aquarena Springs, San Marcos. We could see straight through — the fish, the ground of the river. As the boat moved into deeper water the bottom drifted further away, but you began to see different fish, different things swimming around.</p>', 'shore', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 6, '<h2 class="sm">And I wonder sometimes if we settle for seeing only what can be seen from shallow water.</h2>', '<p>And I wonder sometimes if we settle for seeing only what can be seen from shallow water.</p>', 'shore', null),
  ('c1000000-0000-4000-8000-000000000003', 7, '', '<p><strong>Story — our family boat.</strong> There is a lot you can do with a boat. My wife loves to fish — we used to go out on the lake.</p>', 'shore', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 8, '<h2>Luke 5:4</h2><p class="sub">We could have used Jesus</p>', '<p><strong>Read Luke 5:4.</strong> Jesus instructs to go deeper — cast your nets again. Peter didn''t want to, but he did. Net full — almost sank his boat and the boat that came to help him.</p>', 'shore', 'Read the passage before advancing.'),
  ('c1000000-0000-4000-8000-000000000003', 9, '<h2 class="stage" data-stage="1">There may be more to our faith than what we have experienced so far&hellip;</h2><h2 class="stage" data-stage="2">&hellip;but experiencing it requires us to move beyond where we are.</h2>', '<p>There may be more to our faith than what we have experienced so far&hellip; &hellip;but experiencing it requires us to move beyond where we are.</p>', 'shore', 'One click — second line lands on its own.'),
  ('c1000000-0000-4000-8000-000000000003', 10, '', '<p><strong>Callback — glass-bottom boat.</strong> The boat ride taught me something I didn''t understand until much later: the farther we moved from the shoreline, the more there was to see. Maybe that''s true of many things. And on the other hand — it''s possible to spend years around the water and never discover what''s farther out.</p>', 'shore', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 11, '<h2>Matthew 4:19</h2><p class="sub">A new meaning of fishing</p>', '<p><strong>Matthew 4:19.</strong> They left their fishing careers to become fishers of people. Maybe they weren''t great fishermen — Jesus gave them a promotion. He elevated the concept of fishing: no longer fishers of fish, but fishers of men.</p>', 'shore', null),
  ('c1000000-0000-4000-8000-000000000003', 12, '<h2>Jesus didn''t just change their occupation. He changed their purpose.</h2>', '<p>Jesus didn''t just change their occupation. He changed their purpose. Fishing became more than making a living — it became changing the world.</p>', 'shore', null),
  ('c1000000-0000-4000-8000-000000000003', 13, '<h2>So &mdash; how do you catch a boatload of fish?</h2><p class="sub">Three answers</p>', '<p><strong>The question: how do you catch a boatload of fish?</strong> Three answers follow — cut the rope &middot; stop talking trash &middot; experience open water.</p>', 'shore', null),
  ('c1000000-0000-4000-8000-000000000003', 14, '<p class="kicker">Answer 1 of 3</p><div class="rule-line"></div><h2>Cut the Rope</h2><p class="sub">Stop fishing at the shore</p>', '<p><strong>Answer 1 — Cut the Rope.</strong> Stop fishing at the shore. You can''t discover open water while tied to the dock.</p>', 'open', 'THE BACKGROUND LAUNCHES HERE — beached boat becomes open water. Give it a beat before you speak.'),
  ('c1000000-0000-4000-8000-000000000003', 15, '<h2>Comfort has never launched a mission.</h2>', '<p>Comfort has never launched a mission. If comfort launched something, it would stop being comfortable. There has never been a great step of faith that didn''t create some conflict. If there''s no tension — you''re probably still standing on the shore.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 16, '<h2 class="sm">Most people don''t fail because they don''t care. They fail because they''ve never left the shoreline.</h2>', '<p>Most people don''t fail because they don''t care. They fail because they''ve never left the shoreline.</p><p>Then ask: what does someone''s faith look like that has never left shallow water?</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 17, '', '<p><strong>Story — my first fish.</strong> A perch, about the size of a crunchy taco. I wanted to grill it and invite all my friends over. First-fish excitement can be over-lived.</p>', 'open', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 18, '', '<p><strong>The fish were in deeper water.</strong> The miracle wasn''t at the shore — it was waiting where Peter didn''t want to go. Obedience often feels unreasonable until you see the catch. Peter wasn''t lacking skill; he was lacking expectation. He''d proven he knew how to fish. Jesus wanted to teach him how to trust.</p>', 'open', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 19, '<h2 class="sm">Faith goes deeper when we have something to learn instead of something to prove.</h2>', '<p>Faith goes deeper when we have something to learn instead of something to prove.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 20, '<p class="kicker">Answer 2 of 3</p><div class="rule-line"></div><h2 class="sm">Stop Talking Trash About Deep Water Fishermen</h2><p class="sub">Learn from the people whose nets are already full</p>', '<p><strong>Answer 2 — Stop talking trash about deep water fishermen.</strong> Learn from the people whose nets are already full.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 21, '<h2 class="sm">Criticism is often the language of people who never left the shore.</h2>', '<p>Criticism is often the language of people who never left the shore. Don''t mock what you haven''t experienced. God''s calling is usually much clearer than our excuses — and clarity demands a decision.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 22, '<h2 class="sm">The people that have been there are the ones that can take you there.</h2>', '<p>The people that have been there are the ones that can take you there. You can''t take others to a place you''ve never been.</p><p>Learn from experienced fishermen: people want immediate results, the spotlight without the sacrifices, the miracle without leaving the shoreline, the catch without rowing into deep water.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 23, '<h2 class="sm">The things no one sees bring about the results everyone wants.</h2>', '<p>The things no one sees bring about the results everyone wants.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 24, '<div class="pairs"><div><div class="lab">Nobody sees</div><ul><li>the rowing</li><li>the preparation</li><li>the bait</li><li>the repairing of nets</li><li>the courage</li></ul></div><div class="arw">&rarr;</div><div class="out">They only see the fish.</div></div>', '<p><strong>Nobody sees</strong> the rowing, the preparation, the bait, the repairing of nets, the courage &rarr; they only see the fish.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 25, '<div class="pairs"><div><div class="lab">Nobody sees</div><ul><li>prayers</li><li>Bible study</li><li>mentoring</li><li>inviting</li><li>teaching</li><li>serving</li></ul></div><div class="arw">&rarr;</div><div class="out">They only see the baptisms.</div></div>', '<p><strong>Nobody sees</strong> prayers, Bible study, mentoring, inviting, teaching, serving &rarr; they only see the baptisms.</p><p>Everybody wants the catch. Few people want the deep water.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 26, '<h2>Everybody celebrates the fish. Nobody celebrates the rowing.</h2>', '<p>Everybody celebrates the fish. Nobody celebrates the rowing.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 27, '<p class="kicker">Answer 3 of 3</p><div class="rule-line"></div><h2>Experience Open Water Fishing</h2><p class="sub">Learn the deep things</p>', '<p><strong>Answer 3 — Experience open water fishing.</strong> Learn the deep things.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 28, '', '<p><strong>Story — the pet lobster.</strong></p>', 'open', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 29, '<h2 class="sm">Going out into the deep doesn''t make you stronger. It reveals whether you trust the Captain.</h2>', '<p>Going out into the deep doesn''t make you stronger. It reveals whether you trust the Captain. Faith grows where the shore disappears. An anchored boat by the shore is a very different experience than the open ocean.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 30, '<h2>Boats tied to the same dock eventually bump into each other.</h2>', '<p>Boats tied to the same dock eventually bump into each other. Boats on a mission in open water have the space to grow and experience greater things.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 31, '<p class="kicker">Closing</p><div class="rule-line"></div><ul><li>Dust off your tacklebox &mdash; Matt. 25:29</li><li>Use what God has made available &mdash; Deut. 6:4&ndash;9</li><li>Try new things &mdash; John 21:6</li></ul>', '<p><strong>Closing.</strong> Dust off your tacklebox (Matt. 25:29) &middot; use what God has made available (Deut. 6:4&ndash;9) &middot; try new things (John 21:6).</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 32, '', '<p><strong>Callback — the ark.</strong> A boat can look perfectly safe sitting on dry ground — but that''s not what it was built for.</p>', 'open', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 33, '<h2>The tragedy is not ignorance. The tragedy is unused knowledge.</h2>', '<p>The tragedy is not ignorance. The tragedy is unused knowledge.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 34, '<h2 class="stage" data-stage="1">The goal isn''t simply to get people into the boat.</h2><h2 class="stage" data-stage="2">The goal is to get the boat into the water.</h2>', '<p>The goal isn''t simply to get people into the boat. The goal is to get the boat into the water.</p><p>That''s where you trust God.</p>', 'open', 'One click — the punch line lands on its own. Then: that''s where you trust God.'),
  ('c1000000-0000-4000-8000-000000000003', 35, '<h2>The church was never built to be a marina.</h2>', '<p>The church was never built to be a marina. A church can have a boat, maintain it, repair it, admire it, sit together in it — and still never launch.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 36, '', '<p><strong>Callback — glass-bottom boat, bring it home.</strong> When I got on that boat as a kid, I didn''t know what was waiting farther out. I was already impressed by what I could see when we first got on. But the boat didn''t stay there. It moved. And the farther we went, the more there was to see. Maybe that''s the invitation Jesus is giving us.</p><p>Peter had already been fishing. Already worked. Already used his nets. But Jesus was about to show him something he had never experienced. The difference: Peter had to be willing to go where Jesus told him. Further. Deeper.</p>', 'open', 'Background only.'),
  ('c1000000-0000-4000-8000-000000000003', 37, '<blockquote>What is Jesus waiting to show you that you will never experience from the shoreline?</blockquote>', '<p>What is Jesus waiting to show you that you will never experience from the shoreline?</p>', 'open', 'Ask the room. Then: God didn''t call us to admire the water. He called us to launch into it.'),
  ('c1000000-0000-4000-8000-000000000003', 38, '<h2>Deep water isn''t a place. It''s a decision.</h2>', '<p>Deep water isn''t a place. It''s a decision.</p>', 'open', null),
  ('c1000000-0000-4000-8000-000000000003', 39, '<h2 class="sm">And maybe the greatest thing God still wants to do through your life is something you can''t see from the shoreline.</h2>', '<p>And maybe the greatest thing God still wants to do through your life is something you can''t see from the shoreline.</p>', 'open', 'Final slide. Leave it up.'),
  ('c1000000-0000-4000-8000-000000000003', 40, '', '<p><strong>Background only</strong> — invitation / closing prayer.</p>', 'open', null)
insert into cisco.cisco_deck_state (deck_id, current_slide, is_live, is_blank)
